// Extrahiere Absender + Betreff + Text
const m = $('Strato IMAP (kontakt@)').first().json;
const from = (m.from || m.sender || '');
const subject = m.subject || '';
const body = m.textPlain || m.textHtml || m.text || '';
const emailMatch = (from.match(/[\w.+-]+@[\w-]+\.[\w.-]+/) || [''])[0];
return [{ json: { from, emailMatch, subject, body, receivedAt: m.date } }];

// Schreibe Antwort in lokale JSON-Datei (lead_responses.json) fuer spaeteren Abgleich
const fs = require('fs');
const p = '/home/node/.n8n/lead_responses.json';
let arr = [];
if (fs.existsSync(p)) { try { arr = JSON.parse(fs.readFileSync(p,'utf8')); } catch(e){} }
const r = $('Parse Response').first().json;
arr.push({
  email: r.emailMatch, from: r.from, subject: r.subject,
  body: r.body.slice(0,500), receivedAt: r.receivedAt, loggedAt: new Date().toISOString()
});
fs.writeFileSync(p, JSON.stringify(arr, null, 2));
return [{ json: r }];

